export type Question = {
  id: string;
  prompt: string;
  type: 'single' | 'text';
  options: string[];
};
export type Survey = {
  id: string;
  owner_id: string;
  title: string;
  description: string;
  symbol: string;
  questions: Question[];
  status: string;
  demo: number;
  target: number;
  reward_cents: number;
  created_at: number;
  updated_at: number;
  response_count: number;
};
