export type StoredSurvey = Omit<Survey, 'questions'> & {
  questions: string;
  salt: string;
  owner_id: string;
};
export type StoredResponse = {
  answers: string;
  cohort: string;
  slot: number;
  verified_at: number;
  created_at: number;
};
export type AnalyticsData = {
  survey: Survey;
  count: number;
  questions: (Question & {
    distribution: { option: string; count: number }[];
    textResponses: string[];
  })[];
  cohorts: { label: string; count: number }[];
  cohortsSuppressed: boolean;
  holdingDuration: null;
  newBuyers: null;
  latestVerifiedAt: number | null;
  rows: unknown[];
};
export type CommercialOrder = {
  id: string;
  organization: string;
  plan: string;
  email: string;
  notes: string;
  status: string;
  created_at: number;
};
export type AdminData = {
  surveys: Survey[];
  orders: CommercialOrder[];
  audit: { action: string; target: string; created_at: number }[];
};
export type ResponseReceipt = {
  id: string;
  rewardCents: number;
  claimStatus: string;
};
